public static boolean isSymmetric(int[] a, int lo, int hi) {
    // נשאר איבר אחד או שלא נשאר כלום — סימטרי
    if (lo >= hi) {
        return true;
    }
    // הקצוות שונים — לא סימטרי
    if (a[lo] != a[hi]) {
        return false;
    }
    // בודקים את מה שבפנים
    return isSymmetric(a, lo + 1, hi - 1);
}

public static int maxFrom(int[] a, int i) {
    // האיבר האחרון — הוא הגדול ביותר בקטע
    if (i == a.length - 1) {
        return a[i];
    }
    int rest = maxFrom(a, i + 1);
    if (a[i] > rest) {
        return a[i];
    }
    return rest;
}

