int[] sym = { 1, 3, 5, 3, 1 };
int[] other = { 4, 9, 2, 7 };
System.out.println("סעיף א: " + isSymmetric(sym, 0, sym.length - 1) + " " + isSymmetric(other, 0, other.length - 1));
System.out.println("סעיף ב: " + maxFrom(other, 0) + " " + maxFrom(other, 2));
